begin;
set local search_path = public, extensions;
do $world_pulse_seed$
declare
  v_world uuid;
  v_location uuid;
  v_primary uuid;
  v_template uuid;
  v_character uuid;
  v_existing record;
  v_facts jsonb;
  v_known_ids jsonb;
begin
  select id into strict v_world from public.together_worlds where slug = 'gilded-coast';
  insert into public.together_world_pulse_settings (world_id, enabled) values (v_world, false) on conflict (world_id) do nothing;
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'lightkeep' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'keon-flint' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'the-light-that-sent-ships-west';
  if found and (v_existing.repeat_identity <> 'gilded-coast:major:the-light-that-sent-ships-west' or v_existing.scheduling_rank <> 200 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: gilded-coast/the-light-that-sent-ships-west'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['keon-flint','nadia-storm','talia-wren']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: gilded-coast/the-light-that-sent-ships-west/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A false harbor light draws three inbound vessels toward a shallow reef. Pilots turn two clear; the third grounds without sinking, and the real lighthouse keeps burning throughout.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-light-that-sent-ships-west','gilded-coast:major:the-light-that-sent-ships-west',200,1,'The Light That Sent Ships West','A false harbor light draws three inbound vessels toward a shallow reef. Pilots turn two clear; the third grounds without sinking, and the real lighthouse keeps burning throughout.','Tidemark is a working port on the Gilded Coast, where ships enter through a narrow channel after dark. During the evening tide, crews on three vessels report a steady white light west of the official approach. The light at Lightkeep is still operating. Keon Flint boards the lead vessel and orders a turn; Nadia Storm signals the second from a pilot boat, while Talia Wren verifies the lighthouse lens and logs its position. The third vessel touches reef stone before its captain can change course. Its passengers come ashore safely, but cargo and hull need inspection.

The false light disappears before a watch boat reaches it. A damaged lantern frame is found on a nearby spit, but neither ownership nor intent is established. The channel remains open by daylight with a temporary pilot requirement; every arriving captain must now answer which light they followed.','The real light was on while another drew ships off course. What did each of you verify?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"ec23e96203e95415e9d77fa477bf193437ef76be39c9318468b43e3c56bdd2dd","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
