  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-light-that-sent-ships-west/keon-flint'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Turned the lead vessel','I saw the wrong light from the deck and ordered the turn. I cannot tell who set it from where I stood.','What made you distrust the light?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'nadia-storm' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-light-that-sent-ships-west/nadia-storm'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Warned the second vessel','My flag reached the second ship before it entered the reef bend. I recorded its bearing separately.','How did you reach the second crew?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'talia-wren' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-light-that-sent-ships-west/talia-wren'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Verified Lightkeep','Our lens did not fail. I can show its watch log; the other lantern is a separate question.','Was the lighthouse itself working?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'harbor-court' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'tomas-renn' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'the-charter-revoked-at-sea';
  if found and (v_existing.repeat_identity <> 'gilded-coast:major:the-charter-revoked-at-sea' or v_existing.scheduling_rank <> 201 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: gilded-coast/the-charter-revoked-at-sea'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['tomas-renn','anika-saye','elara-voss']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: gilded-coast/the-charter-revoked-at-sea/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','The Admiralty suspends one privateering charter while its ship is already outside the harbor. A returning crew will enter as lawful sailors or suspected pirates depending on a notice they never received.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-charter-revoked-at-sea','gilded-coast:major:the-charter-revoked-at-sea',201,1,'The Charter Revoked at Sea','The Admiralty suspends one privateering charter while its ship is already outside the harbor. A returning crew will enter as lawful sailors or suspected pirates depending on a notice they never received.','Letters of marque are the Gilded Coast’s narrow legal boundary between privateering and piracy. A Harbor Court ruling suspends Captain Elara Voss’s charter after a casualty complaint, but her vessel sailed before the sealed notice reached the quay. Tomas Renn keeps a safe berth available for its return. Anika Saye checks whether the outgoing packet was ever signed aboard; Elara’s shore officer refuses to forge a receipt.

The ship returns without prizes and its crew disembarks under temporary protection. The court still must decide when the suspension became effective and whether the crew may depart again. The family who brought the complaint has a hearing date, not an answer to its loss.','The crew is ashore, but when did the suspension bind them? What can each of you establish?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"0e006803eb2f0d59648d232d795b3e2b6d9a9f636632a58667a6c1bc87fb56d4","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
