  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Held a safe berth','A legal dispute is no excuse to strand a crew outside the breakwater. The berth did not decide their case.','Why let the ship return?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'anika-saye' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-charter-revoked-at-sea/anika-saye'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Checked the notice trail','I found no signed shipboard receipt. That does not tell me who failed to deliver it.','Did Elara know the charter had been suspended?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'elara-voss' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-charter-revoked-at-sea/elara-voss'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Returned to the hearing','I brought the ship in without a prize and put the crew ashore. I will answer the complaint in court.','What will you say at the hearing?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'arrival-steps' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'bruna-kest' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'the-grain-barge-splits';
  if found and (v_existing.repeat_identity <> 'gilded-coast:major:the-grain-barge-splits' or v_existing.scheduling_rank <> 202 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: gilded-coast/the-grain-barge-splits'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['bruna-kest','celia-mar','seraphine-vale']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: gilded-coast/the-grain-barge-splits/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A grain barge cracks its side while unloading. Workers save much of the cargo, but a wet portion cannot be sold as food and two districts must rewrite their supply plans.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-grain-barge-splits','gilded-coast:major:the-grain-barge-splits',202,1,'The Grain Barge Splits at the Quay','A grain barge cracks its side while unloading. Workers save much of the cargo, but a wet portion cannot be sold as food and two districts must rewrite their supply plans.','Tidemark relies on island catch, local gardens, and grain brought by water. A barge shifts against the quay at low tide, opening a seam below its cargo line. Bruna Kest orders the unloading rig stopped before a worker is crushed. Celia Mar organizes dry storage for the sacks already ashore, while Seraphine Vale calls buyers to separate insured grain from the wet hold rather than let a broker quietly mix them.

No one is hurt. Inspectors condemn the wet sacks and release the dry lot after a physical count. Bread is still available, but prices and kitchen plans change that week. The barge owner says a hidden rock caused the crack; dockworkers point to a hurried mooring order. The harbor survey and work log must be compared before liability is assigned.','The dry grain was saved and the wet grain condemned. Who bears the loss?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"bdf274c3fe262a757611ceef511dc806819279fb40217d1beb7a8c308addd3bb","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
