  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Stopped the unloading rig','The barge moved against the posts. I stopped the lift before asking who was to blame.','How close did the crew come to injury?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'celia-mar' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-grain-barge-splits/celia-mar'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Found dry storage','We kept the rescued sacks separate and fed the shift that carried them. That does not erase the lost wages.','What happens to workers after the barge loss?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'seraphine-vale' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: gilded-coast/the-grain-barge-splits/seraphine-vale'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Separated the grain lots','I rejected a blended sale. Buyers should know which sacks were wet and which were not.','Will food prices rise?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'ferry-hall' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'rafiq-nadir' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'all-ferries-stand-still';
  if found and (v_existing.repeat_identity <> 'gilded-coast:major:all-ferries-stand-still' or v_existing.scheduling_rank <> 203 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: gilded-coast/all-ferries-stand-still'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['rafiq-nadir','sora-bay','mira-cael']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: gilded-coast/all-ferries-stand-still/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','Island pilots refuse departure after a new city-only timetable omits the low-water crossing. Families, markets, and a clinic lose their usual link to the cays for one day.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'all-ferries-stand-still','gilded-coast:major:all-ferries-stand-still',203,1,'All Ferries Stand Still','Island pilots refuse departure after a new city-only timetable omits the low-water crossing. Families, markets, and a clinic lose their usual link to the cays for one day.','The nearby cays are part of everyday Gilded Coast life, not a distant adventure. A posted timetable cuts the morning low-water crossing that brings fishers, school staff, and patients into Tidemark. Rafiq Nadir ties up the first ferry rather than sail a route the island council did not approve. Sora Bay gathers names of people who need transport; Mira Cael checks which signal and berth windows are actually available.

An emergency medical crossing proceeds under a separate permit. Other passengers wait until a public afternoon negotiation restores a temporary low-water service. The pilots return to work, but the timetable is not settled. The next version must be signed by both the city office and cay representatives.','The pilots are sailing again under a temporary agreement. What must change in the timetable?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"de7e41ca07bdd9f7365bb69b799db66e306c1c5141da83c668a9e48e608320b1","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
