  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Held the ferry','I did not leave passengers guessing: I told them exactly why we stopped and what crossing was still permitted.','Why did the pilots stop?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from your own observations. Do not claim another witness''s private reason."]}'::jsonb);
