  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-market-fire','gilded-coast:major:the-market-fire',204,1,'Fire Above the Night Market','A cooking flue ignites an awning over the Night Market. Stallholders put the flames out before they reach the stores, but smoke drives hundreds into one narrow lane.','The Night Market is Tidemark’s crowded evening meeting place. A vendor’s cooking flue throws sparks into a patched awning. Javier Ro cuts the fuel to nearby braziers; Inez Sol opens a backstage passage for families to leave without pushing through the main lane; Tomas Renn directs people around a blocked cart while the volunteer water line reaches the roof.

The fire is contained to two awnings and one empty upper room. Nobody dies, though smoke sends several people to the clinic. Vendors reopen in stages after flues and exits are inspected. The question now is why the emergency lane had been narrowed by a permitted delivery cart at the busiest hour.','The flames are out. Which access rule needs changing before the market fills again?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"76f883e95d73be254512af86d46e6052998f232eb4845faf1bc4a62b872d80ae","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
