  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-blackfin-boarding','gilded-coast:major:the-blackfin-boarding',205,1,'Blackfin Boards a Patrol Cutter','Captain Mara Blackfin seizes an Admiralty patrol cutter outside the bay. Both crews report wounded sailors; the cutter returns under a white flag while the reason for the boarding remains disputed.','The Gilded Coast’s free captains and Admiralty have argued for years over who controls the island routes. At dawn, Mara Blackfin’s crew boards a patrol cutter carrying seized fishing gear. The clash leaves sailors wounded on both decks. Bastien Crow arranges a neutral tow into port; Amara Kade treats people from both crews; Sora Bay asks for an inventory of the confiscated gear before either captain turns the action into a victory story.

The cutter and its wounded return under a white flag. No one aboard is declared dead in the verified clinic list, but the patrol’s seizure order and Mara’s warning shots are still under review. The fishing families want their tools returned; the court wants testimony from people who stood on each deck.','Both crews are ashore. Which records could narrow their contradictory accounts?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"bfaaf0d670c69d36d50f5fa391cfca2fce0337641df815c44c3744ad239f4ae7","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
