  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-tide-clock-stops','gilded-coast:major:the-tide-clock-stops',206,1,'The Tide Clock Stops','Tidemark’s public tide clock freezes before a spring low. Ferries and cargo crews catch the error in time, but an unmarked small boat grounds near the cays.','The tide clock in Ferry Hall is a shared reference for people who do not own charts. Its hands stop for nearly an hour while the posted board continues to show the previous high-water time. Mira Cael confirms the actual waterline from the signal house and flags ferries to wait. Nadia Storm checks the cay landing and helps an unmarked small boat off the mud without pretending the public clock was its only navigational aid.

The clock is repaired and cross-checked against a hand-written tide board. The grounded boat’s passengers are safe, but its owner had no current chart aboard. Port staff have to decide how prominently to post a second independent tide reference for visitors and working crews.','The hands move again. How should the harbor verify tide information next time?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"ece0d2818186dcb07fbb7aeed56133c48c40af3094c05c9cafc8e521c791c9d6","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
