  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-bank-doors-stay-shut','gilded-coast:major:the-bank-doors-stay-shut',207,1,'The Bank Doors Stay Shut','The Salt Ledger Bank closes its doors after a missing convoy ledger sparks a run on deposits. Wages and repair payments stall until a count confirms what funds are actually available.','Salt Ledger finances ships and household repairs across Tidemark. A convoy account page goes missing the morning several crews expect wages. Julian Mercer refuses to invent a balance from the remaining pages. Seraphine Vale closes withdrawals for a bounded count, while Celia Mar demands that workers receive a dated explanation and emergency cash for food rather than a polished reassurance.

The count finds enough liquid funds to cover wages, and the bank reopens a limited payroll window before dusk. The missing page may be misfiled or removed; no depositor is accused without evidence. The bank’s emergency procedure is now public business because a private record stopped working people from accessing their pay.','The wage window reopened. What caused the ledger gap, and who pays for the delay?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"cd5cfa6cad631f1a830803dd23c628145f3d13a14298a205fb4629a824027e01","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
