  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-breakwater-gives-way','gilded-coast:major:the-breakwater-gives-way',208,1,'The Breakwater Gives Way','A repaired section of the sea wall collapses under a high tide. Nearby homes and workshops stay dry after crews open an old drainage channel, but the port loses its sheltered east berth.','Breakwater Point protects much of Tidemark’s inner harbor. A newly repaired wall section slumps under a high tide; waves strike the east berth before anyone can move its moored craft. Bruna Kest sends shipwrights to release the vessels. Oren Gale reads the next tide peak, and Sami Haddad opens a marked drainage cut that directs water away from nearby homes.

No occupied building floods. The east berth closes for inspection, shifting cargo and ferry arrivals elsewhere. The work ledger shows the repair passed an earlier check, so engineers must compare the tested section with the stones that actually failed before blaming either crew or weather.','Homes stayed dry, but the berth is closed. What must the repair review establish?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"e5623f82d933d18cf20f3e9799fdd7caff96b6bd40bad18f58800106acfe58d1","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
