  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-ferry-that-did-not-ring','gilded-coast:major:the-ferry-that-did-not-ring',209,1,'The Ferry That Did Not Ring','A cay ferry fails to sound its scheduled arrival bell. It is found sheltered behind a headland with passengers safe, but its signal line was deliberately cut after departure.','Every ferry arriving in Tidemark sounds a bell so the waiting hall can account for passengers. When Rafiq Nadir’s vessel misses its mark, Mira Cael raises a search signal instead of calling it lost. Keon Flint follows a safe headland route and finds the ferry waiting out a squall. The passengers are safe; a severed signal line means the captain could not warn the port of the delay.

The ferry returns under escort. The cut is clean enough to require investigation, but that alone does not establish who made it or when. Passengers describe the delay differently, and the port keeps the vessel out of service until the line, crew log, and boarding record are checked.','Everyone returned safely. Who can establish when the signal line was cut?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"d3746a30cd5fe704f3607643b01806d6cec10ab05366f2e2b802058bf6b83606","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
