  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-spring-tastes-of-iron','gilded-coast:major:the-spring-tastes-of-iron',210,1,'The Spring Tastes of Iron','Residents report an iron taste in Tidemark’s public spring. The city closes one water outlet, distributes stored water, and traces the change to a corroded pipe section rather than the spring itself.','Tidemark grew around a freshwater spring. When several households report a metallic taste from the lower public outlet, Amara Kade asks them to stop using that tap until a sample is checked. Anika Saye records which deliveries came from the outlet; Celia Mar helps distribute sealed water jars without suggesting every home supply is unsafe.

A corroded branch pipe explains the iron in that outlet, and the unaffected spring is independently sampled. Crews replace the pipe and test the flow before reopening it. The short closure leaves a practical question: why did two earlier taste complaints remain in separate offices without reaching the maintenance ledger?','The branch pipe has been replaced. Why did the earlier complaints not reach repair crews?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"884c9a1f0b68a304e896696900793410190615abbca2270884b693c6dbaf0a5e","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
