  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'sails-under-the-black-flag','gilded-coast:major:sails-under-the-black-flag',212,1,'Sails Under the Black Flag','Three armed vessels enter sight of the outer cays flying Blackfin colors. One is hers; the other two are not. Islanders shelter boats while captains identify who is using the flag.','Captain Mara Blackfin’s black flag can warn patrols away from island waters, but it also gives imitators a useful disguise. Three armed vessels approach the cays at dusk. Mara claims one cutter; Sora Bay directs fishing boats into sheltered water; Bastien Crow keeps the Admiralty battery from firing at a silhouette while signalers seek actual identification.

The two unknown vessels turn away before reaching the village. No clash occurs, and no one can claim the retreat proves whose ships they were. A recovered signal scrap carries a copied Blackfin mark; the island council demands a better identification code before the next armed approach.','The unknown ships left. What identification can the cays trust next time?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"925644426d3bf05898337e45d26b5a730c4a3b5b68b7cd66de9e5d3e5d7e3b83","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
