  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-auction-of-a-stolen-bell','gilded-coast:major:the-auction-of-a-stolen-bell',213,1,'The Bell Listed for Auction','A ship’s bell from a vessel lost in convoy year appears in the Gilt Auction catalog. Two families claim it, and the sale is halted while its provenance is checked.','A bell can be both salvage and a family memorial on the Gilded Coast. The Gilt Auction lists a brass ship’s bell attributed to a vessel lost in convoy year. Iria Montrose finds a repair seam matching an old sketch. Seraphine Vale freezes the sale when two households produce different ownership papers; Nera Tide explains where she found the bell but cannot establish who removed it from the wreck.

The bell stays in neutral storage. The auction house returns bids without naming either family dishonest. One document may record ship ownership and the other the crew fund that bought the bell; Harbor Court must decide which claim the surviving families actually intended.','The bell remains unsold. Which record can explain who had the right to pass it on?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"13f47be890102f0719d943710c16d0420debf1e32e64031146a551ee59cfc554","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
