  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-harbor-goes-dark','gilded-coast:major:the-harbor-goes-dark',214,1,'The Harbor Goes Dark','A squall extinguishes the quay lanterns and the signal-house lamps at once. Ferries hold position while workers hand-carry covered lights to the landing; the pattern points to one shared oil delivery.','Tidemark has no electric grid; its oil lamps are small pieces of public infrastructure. A sudden squall puts out lamps along the quay and inside the signal house. Mira Cael raises a spare flag by daylight left in the sky. Levi Ash and Nico Solari carry covered lamps along the safe upper route, while Rafiq Nadir holds a ferry off the landing until the steps can be seen.

Every ferry docks safely once the covered lights are placed. Inspectors find water in cans from one delivery lot; the oil supplier is contacted and other public lamps are checked. The squall caused the outage, but the shared fuel problem explains why so many lamps failed together.','The ferries docked. Which lamps shared the contaminated fuel lot?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['worldwide','major-incident']::text[],'{"contentDigest":"ebc9fc0db27d4962d22c7cc3cc160ae8bb8330db56db3a257bc7cddaa2e4da1b","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
